/**
 * Test flow for getEmailHeader action
 * Demonstrates getting email header information
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testGetEmailHeader = Flow(
    {
        $id: Now.ID['test_get_email_header_flow'],
        name: 'Test Get Email Header',
        description: 'Tests the getEmailHeader core action',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_get_email_header_trigger'] },
        {
            table: 'sys_email',
            condition: 'type=received',
            run_flow_in: 'background',
        }
    ),
    (_params) => {
        const result = wfa.action(
            action.core.getEmailHeader,
            { $id: Now.ID['test_get_email_header_action'] },
            {
                email_record: wfa.dataPill(_params.trigger.current.sys_id, 'reference'),
                target_header: 'Message-ID',
            }
        )

        wfa.action(
            action.core.log,
            { $id: Now.ID['test_get_email_header_log'] },
            {
                log_level: 'info',
                log_message: `getEmailHeader outputs: header_value=${wfa.dataPill(result.header_value, 'string')}`,
            }
        )
    }
)
